(602, 1081, 7, 'Komplain pasien :\r\nbidan ros endang,menghubungi pu jam 21.00,pasien berobat ke poli dr finny sore,membawa anak nya 2 orang,(kakak-adik),keluhan adik nya demam dan batuk sudah beberapa hari,dan kakak nya baru 1 hari,dr anjurakan p/labor adik nya,dan darah yang di ambil darah adik ny,namun hasil yang keluar tidak atas nama adik nya,\r\nros endang hub asisten dr finny(sr febby),hasil labor tersebut sudah konfirmasi kelabor mmg salah dan sudah di ganti dengan nama pasien yg benar,dan hasil labor yg ditunjukan ke dr finny atas nama pasien yang p/labor,\r\ndr finny meresepkan obat ,dan obat di bawa pasien pulang,\r\nsetelah poli usai keluarga pasien yang bersangkutan datang dan bertemu bidan ros endang,mengatakan mana yang obat adik ny dan kakak nya yang betul,karena saat berobat yang banyak keluhan dari bberapa hari ini adik nya,tapi yang dapat obat malah kakak ny,\r\nbidan endang hub feby,untuk jelaskan tapi pasien tidak mau menunggu dan meminta mencari no dr finny dari kerabat nya saja,', NULL, 1, '2022-10-22 19:25:49', '2022-10-24 07:48:32'),
