(642, 1153, 7, 'ny sri havina 14-06-1970 ,73-02-35 d/ tumor thyroid sinistra +dm (pas dr ari rencana op jam 17 batal karena hasil ft4 1.78 ,tsh 0.74 ) gdr 287 ,sgpt 53  sdh co dr alex candra th /thyrozol 5mg 1x1 op lanjut ,konsul anestesi (dr rinal nanti lihat di ok ,pas di antar ke ok di lihat sm dr ari dan dr rinal ,dr rinal tdk berani utk op ,di konfirmasi lg ke dr alex c ,rawat sj stabilkan hasil tshnya ,dari dr ari dpjp ganti ke dr alex c sj. Dr. anesthesi (dr. Rinal) tidak previsit di ruangan.', NULL, 1, '2022-11-15 18:47:47', '2022-11-16 07:35:18'),
