(768, 1375, 32, 'Pasien dr. daan a.n Ibu Fitania tgl lahir 01-05-1965 rm 00.28. 12.75 dengan diagnosa ca mammae dextra + perbaikan KU pasien awalnya berobat ke IGD dengan keluhan nyeri payudara kiri lalu br. vicky menelfon ke poli dr. daan dan menganjurkan pasien untuk ke poli dr. daan. setelah diperiksa oleh dr. daan pasien dianjurkan untuk rawat inap lalu asisten menganjurkan pasien untuk periksa darah rutin dan ro thoraks lalu pasien di registrasikan ke IGD untuk menggunakan BPJS dan sudah di registrasikan oleh IGD. sudah periksa darah, ro thoraks, rapid antigen dan petugas labor pun menelfon ke poli dan menyampaikan hasil Hb pasien 6,03. lalu sr. elsa menelpon dr. daan dan mengkonfirmasi hasil labor pasien kwmudian dr. daan menganjurkan untuk pasien dikonsulkan ke penyakit dalam dr. alex chandra untuk tindakan selanjutnya. sr. sofi menghubungi dr. alex chandra untuk konsul penyakit dalam pasien dr. daan an ibu fitania dg ca mamae dextra + perbaikan ku dan hb 6,03 dari dr. alex crossmatch 2 kantong prc.  kemudian kami memang infus dan pasien lalu pasien minta agar infus dipasang diruangan saja krna pasien sudah lelah dan minta pulang istirahat terlebih dahulu. kami sudah menghubungi PU (sr. gusrida), PU sudah berbicara dengan pasien sendiri dan keluarga pasien tetap minta pulang dahulu krna ingin beristirahat malam ini dirumah. dan keluarga sudah berusaha untuk membujuk pasien tetapi pasien tetap ingin pulang dan tidak mau. administrasi sudah di urus oleh keluarga\r\nka. instalasi poli sudah tau dan pj ruangan sudah tau. DPJP dan dokter konsulan sudah dikasih tau.', 'mengedukasi pasien dan keluarga \r\nmenjelaskan prosedur tolak rawat', 1, '2023-01-28 19:29:13', '2023-01-28 21:48:28'),
